const $ = (s, root = document) => root.querySelector(s);
const esc = (value = '') => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes = {
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  layers:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',
  folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l3 3h6a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z"/><path d="M3 9h18"/>',
  book:'<path d="M12 5v16M12 5C8 2 4 3 2 4v15c4-2 7-1 10 2 3-3 6-4 10-2V4c-3-1-6-2-10 1Z"/>',
  chart:'<path d="M4 3v18h17M9 16v-5M14 16V7M19 16V3"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  sparkle:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3ZM20 2v4M18 4h4"/>',
  alert:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3h.01"/>',
  file:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9l-7-7Z"/><path d="M14 2v7h7M7 13h10M7 17h7"/>',
  upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v5a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-5"/>',
  close:'<path d="m6 6 12 12M6 18 18 6"/>',
  link:'<path d="m10 13 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${shapes[name] || shapes.file}</svg>`;
const date = value => new Date(value).toLocaleDateString('en-MY', {day:'numeric',month:'short',year:'numeric'});
const time = value => new Date(value).toLocaleString('en-MY', {day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const colors = {'In progress':'blue','New':'blue','Resolved':'green','Verified':'green','Verified historical fix':'green','High':'green','Awaiting validation':'amber','Workaround':'amber','Medium':'amber','Insufficient evidence':'amber','Unresolved':'red','Low':'red','Escalated':'purple','Outdated':'red','Reviewed':'blue','Likely solution':'blue','Accepted':'green','Rejected':'red'};
const badge = text => `<span class="badge ${colors[text] || colors[text.replace(' confidence','').replace(' priority','')] || ''}">${esc(text)}</span>`;
const btn = (text, action, primary = false, symbol = '') => `<button class="btn ${primary ? 'primary' : ''}" data-action="${action}">${symbol ? icon(symbol) : ''}${text}</button>`;
const option = (value, chosen) => `<option ${value === chosen ? 'selected' : ''}>${esc(value)}</option>`;
const empty = (title, text, action = '') => `<div class="empty">${icon('search')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
const callout = (text, kind = '', symbol = 'sparkle') => `<div class="callout ${kind}">${icon(symbol)}<div>${text}</div></div>`;
let state, current, draft, toastTimer, aiConnection;
let filters = {q:'', status:'All statuses', type:'All types'}, knowledge = {q:'', type:'All sources'};

async function api(path, data) {
  const res = await fetch('/api' + path, data === undefined ? {} : {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(data)});
  const body = await res.json();
  if (!res.ok) throw new Error(body.error || 'The request could not be completed.');
  return body;
}
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 5000); }
async function refresh() { state = await api('/state'); render(); }
function route() { const [page = 'dashboard', id, tab = 'overview'] = location.hash.slice(1).split('/'); return {page,id,tab}; }
function go(path) { if(location.hash === '#' + path) render(); else location.hash = path; }
function stats() {
  const rows = state.investigations;
  return {active: rows.filter(x => ['New','In progress','Awaiting validation'].includes(x.status)).length, resolved:rows.filter(x => x.status === 'Resolved').length, unresolved:rows.filter(x => ['Unresolved','Escalated'].includes(x.status)).length, gaps:rows.filter(x => x.status === 'Unresolved' || x.analysis?.state === 'Insufficient evidence')};
}
function stat(label, value, note, symbol, green = false) { return `<div class="stat"><div class="stat-head">${label}<span class="stat-icon">${icon(symbol)}</span></div><strong>${value}</strong><small class="${green ? 'green' : ''}">${note}</small></div>`; }
function heading(title, subtitle, action = btn('New investigation','new',true,'plus')) { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`; }
function render() {
  if (!state) return;
  const r = route();
  const titles = {dashboard:'Dashboard',investigations:'Investigations',knowledge:'Knowledge',insights:'Insights'};
  const page = titles[r.page] ? r.page : 'dashboard';
  current = r.id ? state.investigations.find(x => x.id === r.id) : null;
  document.title = `${current?.title || titles[page]} · Solution Intelligence`;
  $('#app').innerHTML = `<aside class="sidebar"><a class="brand" href="#dashboard" aria-label="Solution Intelligence home"><div class="brand-icon">${icon('layers')}</div><div><strong>Solution<br>Intelligence</strong><small>ENGINE / WORKSPACE</small></div></a><div class="eyebrow">Workspace</div><nav class="nav" aria-label="Main navigation">${[['dashboard','grid'],['investigations','folder'],['knowledge','book'],['insights','chart']].map(([p,i]) => `<a href="#${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${titles[p]}</span>${p==='investigations'?`<span class="nav-count">${state.investigations.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="scope"><div class="scope-head">${icon('shield')} Customer workspace</div><small>Current scope</small><strong>${esc(state.customer)}</strong><small>Local customer scope</small></div><div class="profile"><div class="avatar">${esc(state.user.slice(0,2).toUpperCase())}</div><div><strong>${esc(state.user)}</strong><small>Support consultant</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <span>${titles[page]}</span>${current?`<span>/</span><span>${esc(current.ticket_id || current.id)}</span>`:''}</div><div class="top-actions"><span>Enterprise application support</span><span class="demo-pill"><i class="dot"></i> MONGODB WORKSPACE</span></div></header><main class="main" id="main">${r.id && page==='investigations' ? current ? workspace(r.tab) : empty('Investigation not found','This investigation is unavailable in your customer workspace.','<a class="btn" href="#investigations">Back to investigations</a>') : page==='dashboard' ? dashboard() : page==='investigations' ? investigationList() : page==='knowledge' ? knowledgePage() : insights()}</main></div>`;
  document.querySelectorAll('.nav a').forEach(link => link.setAttribute('aria-label', titles[link.hash.slice(1)]));
}
function dashboard() {
  const x=stats(), activity=state.investigations.flatMap(i=>i.timeline.map(e=>({...e,id:i.id,ticket:i.ticket_id}))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,4);
  const problems=state.sources.filter(s=>s.index_status!=='Ready' || s.embedding_model!==state.services.embedding_model || s.validation==='Outdated');
  return `${heading('Your investigation workspace','Investigate real tickets with your organisation’s knowledge.')}${serviceBanner()}<section class="welcome"><div><div class="eyebrow">Evidence-led support</div><h2>Your knowledge. Your tickets. Traceable recommendations.</h2><p>Upload your knowledge documents, create an investigation, and let AI retrieve and explain the supporting evidence.</p></div><div class="welcome-icon">${icon('sparkle')}</div></section><section class="stats">${stat('Active investigations',x.active,'Open in this workspace','folder')}${stat('Resolved cases',x.resolved,'Recorded by consultants','check',true)}${stat('Unresolved / escalated',x.unresolved,'Further investigation needed','clock')}${stat('Knowledge sources',state.sources.length,`${state.sources.filter(s=>s.index_status==='Ready').length} indexed for retrieval`,'book')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Recent investigations</h2><a class="btn ghost" href="#investigations">View all ${icon('arrow')}</a></div>${ticketTable(state.investigations.slice(0,5),true)}<div class="table-foot">Only your workspace records are shown. All changes persist in MongoDB.</div></section><aside class="side-stack"><section class="panel"><div class="panel-head"><h2>Recent activity</h2>${icon('clock')}</div><div class="activity">${activity.length?activity.map(e=>`<div class="activity-row"><span class="activity-mark">${icon('file')}</span><div><a href="#investigations/${esc(e.id)}/timeline"><h3>${esc(e.kind)} · ${esc(e.ticket || e.id)}</h3></a><p>${esc(e.text.slice(0,90))}</p><time>${time(e.at)}</time></div></div>`).join(''):'<p class="muted">Activity appears when you create your first investigation.</p>'}</div></section><section class="panel"><div class="panel-head"><h2>Needs attention</h2>${badge(`${x.gaps.length+problems.length} alerts`)}</div>${x.gaps.map(g=>`<a class="gap-alert" href="#investigations/${esc(g.id)}/recommendations"><h3>${esc(g.title)}</h3><p>More evidence needed</p></a>`).join('')}${problems.map(s=>`<div class="gap-alert"><button class="btn ghost" data-source="${esc(s.id)}">${esc(s.title)}</button><p>${esc(s.index_status==='Ready'?'Review or reindex this source':s.index_error || 'Indexing needed')}</p></div>`).join('')}${!x.gaps.length&&!problems.length?'<div class="panel-body muted">No outstanding alerts.</div>':''}</section></aside></div>`;
}
function serviceBanner() {
  const q=state.services.quota;
  const quota=q?` · ATLAS budget ${q.minute_remaining}/${q.per_minute} this minute, ${q.daily_remaining}/${q.per_day} today (UTC)`:'';
  return `<section class="connection-strip"><span>${icon('shield')} MongoDB: ${esc(state.services.database)}</span><span title="Restart ATLAS after changing .env to apply the new model.">${icon('sparkle')} Gemini: ${esc(aiConnection || state.services.ai)} · ${esc(state.services.model)}${esc(quota)}</span><button class="btn small" data-action="check-ai" title="Uses one Gemini generation request.">Check AI connection</button></section>`;
}
function ticketTable(rows, compact=false) {
  if (!rows.length) return empty('No investigations found','Try different filters, or create an investigation to get started.',btn('New investigation','new',true,'plus'));
  return `<div class="table-wrap"><table><thead><tr><th>Investigation</th>${compact?'':'<th>Type / classification</th>'}<th>Status</th><th>${compact?'Priority':'Evidence'}</th>${compact?'':'<th>Updated</th>'}</tr></thead><tbody>${rows.map(x => `<tr><td><a class="ticket-title" href="#investigations/${esc(x.id)}/overview">${esc(x.title)}</a><div class="ticket-meta"><span class="mono">${esc(x.ticket_id || x.id)}</span><span>· ${esc(x.application)}</span></div></td>${compact?'':`<td>${esc(x.type)}<div class="ticket-meta mt">${esc(x.analysis?.classification || 'Not analysed')}</div></td>`}<td>${badge(x.status)}</td><td>${compact?`<span class="badge ${x.priority==='High'?'amber':x.priority==='Critical'?'red':''}">${esc(x.priority)}</span>`:badge(x.analysis?.state || 'Not analysed')}</td>${compact?'':`<td>${date(x.updated_at)}</td>`}</tr>`).join('')}</tbody></table></div>`;
}
function filteredTickets() { return state.investigations.filter(x => (x.title+' '+x.ticket_id+' '+x.application).toLowerCase().includes(filters.q.toLowerCase()) && (filters.status==='All statuses'||x.status===filters.status) && (filters.type==='All types'||x.type===filters.type)); }
function investigationList() { return `${heading('Investigations','A clear path from ticket intake to a verified outcome.')}<section class="panel"><div class="filters"><div class="search">${icon('search')}<input aria-label="Search investigations" id="ticket-search" value="${esc(filters.q)}" placeholder="Search by ticket, issue or application…"></div><select id="status-filter" aria-label="Filter by status">${['All statuses','New','In progress','Awaiting validation',...['Resolved','Workaround','Unresolved','Escalated','Closed - other']].map(v=>option(v,filters.status)).join('')}</select><select id="type-filter" aria-label="Filter by ticket type">${['All types','Incident','Service request','Problem','Change request'].map(v=>option(v,filters.type)).join('')}</select></div><div id="tickets-table">${ticketTable(filteredTickets())}</div><div class="table-foot">Customer scope: ${esc(state.customer)} · All dates shown in your local time</div></section>`; }
function workspace(tab) {
  const x = current;
  const tabs = [['overview','Overview'],['itil','ITIL workflow'],['workspace','Solution workspace'],['timeline','Timeline'],['recommendations','Recommendations'],['evidence','Evidence & Notes'],['outcome','Outcome']];
  const active = tabs.some(([t])=>t===tab) ? tab : 'overview';
  return `<div class="workspace-head"><div class="action-row"><a class="btn ghost" href="#investigations">Investigations</a><span class="muted">/</span><span class="mono muted">${esc(x.ticket_id || x.id)}</span></div><h1>${esc(x.title)}</h1><div class="workspace-meta">${badge(x.status)}<span>${esc(x.type)}</span><span>·</span><span>${esc(x.customer)}</span><span>·</span><span>${esc(x.application)} / ${esc(x.version)}</span></div></div><nav class="tabs" aria-label="Investigation sections">${tabs.map(([t,n])=>`<a href="#investigations/${esc(x.id)}/${t}" class="${active===t?'active':''}" ${active===t?'aria-current="page"':''}>${n}</a>`).join('')}</nav>${({overview:overview,itil:itilPage,workspace:workspacePage,timeline:timelinePage,recommendations:recommendations,evidence:evidencePage,outcome:outcomePage}[active])()}<p class="footer-note">Recommendations support your investigation. A verified historical fix still needs testing in the current customer system.</p>`;
}
function details(items) { return `<div class="detail-list">${items.map(([k,v])=>`<div class="detail-item"><span>${k}</span><strong>${esc(v || 'Not specified')}</strong></div>`).join('')}</div>`; }
function itilPage() {
  const x=current, d=x.itil || {};
  const stages=[['clarification','Clarification'],['investigation_notes','Investigation'],['functional_solutioning','Functional solutioning'],['technical_solutioning','Technical solutioning'],['change_stages','Approval, development & deployment'],['verification','Verification']];
  return `<div class="stack"><section class="panel"><div class="panel-head"><h2>Ticket lifecycle</h2>${badge(x.type)}</div><div class="panel-body"><p class="description">${esc(d.lifecycle_path || (x.type==='Change request'?'Creation → Acceptance → Acknowledgment → Clarification → Solutioning → Approval → Development → Deployment → Verification → Closure':'Creation → Acceptance → Acknowledgment → Clarification → Investigation → Solutioning → Verification → Closure'))}</p><p class="hint">Imported stage notes have no individual timestamps. Original ticket dates are preserved.</p>${details([['Platform / module',[d.platform,d.module].filter(Boolean).join(' / ')],['Component',d.component],['Scenario',d.scenario_group],['Original status',d.original_status],['Resolution quality',d.resolution_quality],['Resolution hours',d.resolution_hours==null?'Not provided':String(d.resolution_hours)],['Linked tickets',d.linked_ticket_ids],['Visibility',d.visibility]])}</div></section>${stages.map(([key,label])=>`<section class="panel"><div class="panel-head"><h2>${label}</h2></div><div class="panel-body"><p class="description">${esc(d[key] || 'No imported notes for this stage.')}</p>${x.timeline.filter(e=>e.date_known!==false && (e.kind===label || e.kind===key)).map(e=>`<p class="description mt">${esc(e.text)}</p>`).join('')}</div></section>`).join('')}<section class="panel"><div class="panel-head"><h2>Root cause and references</h2></div><div class="panel-body"><p class="description">${esc(d.root_cause || 'Root cause not recorded.')}</p><p class="description mt">${esc(d.sources || 'No external references supplied.')}</p><p class="hint">References came from the imported ticket and have not been fetched or independently validated.</p></div></section></div>`;
}
function overview() {
  const x=current;
  return `<div class="content-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Reported issue</h2>${badge(x.priority+' priority')}</div><div class="panel-body"><p class="description">${esc(x.description)}</p></div></section><section class="panel"><div class="panel-head"><h2>Investigation guidance</h2><span class="source-type">${icon('sparkle')} Evidence engine</span></div><div class="panel-body">${x.analysis?callout(`<strong>${esc(x.analysis.state)}</strong><p>${esc(x.analysis.summary)}</p>`,x.analysis.state==='Insufficient evidence'?'warning':''):callout('Review the ticket context, then search permitted knowledge for relevant historical resolutions.')}<p class="hint">AI uses your indexed knowledge, semantic search and cited source excerpts. Configure your API key in .env before analysing.</p><div class="action-row mt">${x.outcome?'<span class="muted">Outcome recorded</span>':btn(x.analysis?'Refresh evidence':'Find supporting evidence','analyze',true,'sparkle')}${x.analysis?`<a class="btn" href="#investigations/${x.id}/recommendations">Review ${x.analysis.results.length} recommendations ${icon('arrow')}</a>`:''}</div></div></section></div><aside class="panel"><div class="panel-head"><h2>Ticket context</h2>${icon('shield')}</div><div class="panel-body">${details([['Customer scope',x.customer],['Application / release',x.application+' / '+x.version],['Error code',x.error_code],['Customisation',x.customisation],['Classification',x.analysis?.classification || 'Pending analysis'],['Created',time(x.created_at)]])}</div></aside></div>`;
}
function timelinePage() { return `<section class="panel"><div class="panel-head"><div><h2>Investigation timeline</h2><p>Ticket communications, evidence, decisions and outcomes</p></div><a class="btn small" href="#investigations/${current.id}/evidence">${icon('plus')} Add note</a></div><div class="timeline">${[...current.timeline].sort((a,b)=>a.at.localeCompare(b.at)).map(e=>`<article class="timeline-item"><div class="timeline-title"><strong>${esc(e.kind)}</strong><span class="muted">${e.date_known===false?'Stage date not supplied':time(e.at)}</span></div><p>${esc(e.text)}</p><small>${esc(e.author)} · ${esc(e.source)}</small></article>`).join('')}</div></section>`; }
function recommendations() {
  const a=current.analysis;
  if (!a) return `<section class="panel">${empty('Start with the evidence','Search permitted knowledge using this ticket’s symptoms, application, version and investigation history.',current.outcome?'':btn('Find supporting evidence','analyze',true,'sparkle'))}</section>`;
  return `<div class="stack">${callout(`<strong>${esc(a.state)}</strong><p>${esc(a.summary)}</p>`,a.state==='Insufficient evidence'?'warning':'')}${a.next_steps?.length?`<section class="panel"><div class="panel-body"><h2>Next investigation steps</h2><ol class="steps">${a.next_steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></div></section>`:''}${a.results.length?`<div class="action-row"><span class="muted">${a.results.length} ranked sources</span><span class="hint">Hybrid relevance is not a probability of success. AI confidence still requires consultant validation.</span></div>`:''}${a.results.map((r,i)=>`<article class="panel recommendation"><div class="panel-body"><div class="rec-top"><div class="rank">${String(i+1).padStart(2,'0')}</div><div><h2>${esc(r.title)}</h2><div class="rec-info">${badge(r.label)}${badge(r.confidence+' confidence')}<span class="badge">${r.score} relevance points</span>${current.decisions[r.source_id]?badge(current.decisions[r.source_id]):''}</div></div></div><ul class="reasons">${r.reasons.map(reason=>`<li>${icon('check')}${esc(reason)}</li>`).join('')}</ul>${r.warnings.map(w=>`<div class="mt">${callout(esc(w),'warning','alert')}</div>`).join('')}${r.quote?`<blockquote class="source-quote">${esc(r.quote)}<small>${esc(r.source_id)} · ${esc(r.chunk_id)}</small></blockquote>`:""}<div class="section-label">Suggested investigation steps</div><ol class="steps">${r.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="rec-actions"><button class="source-ref" data-source="${esc(r.source_id)}">${icon('file')}${esc(r.source_id)} · ${esc(r.source_type)}</button><div class="action-row">${current.outcome?'':`<button class="btn small" data-decision="Rejected" data-id="${esc(r.source_id)}">Reject</button><button class="btn small ${current.selected_source===r.source_id?'':'primary'}" data-decision="Accepted" data-id="${esc(r.source_id)}">${icon('check')}${current.selected_source===r.source_id?'Selected for validation':'Select for validation'}</button>`}</div></div></div></article>`).join('')}${!a.results.length?`<section class="panel">${empty('No relevant sources found','Add exact error text, system details or specialist findings in Evidence & Notes, then run the search again.',`<a class="btn" href="#investigations/${current.id}/evidence">Add investigation evidence</a>`)}</section>`:''}</div>`;
}
function evidencePage() {
  const refs=current.analysis?.results || [];
  return `<div class="content-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Add investigation evidence</h2></div><form class="panel-body" id="note-form"><label>Evidence type<select name="kind"><option>Note</option><option>Test</option><option>Attachment</option><option>Acceptance</option><option>Acknowledgment</option><option>Clarification</option><option>Investigation</option><option>Functional solutioning</option><option>Technical solutioning</option><option>Approval</option><option>Development</option><option>Deployment</option><option>Verification</option></select></label><label class="mt">Investigation notes or test results<textarea name="text" required maxlength="12000" placeholder="What did you investigate? Record the environment, observations and source references."></textarea></label><p class="hint">Paste relevant attachment text and its original filename, or upload an attachment below. New evidence clears previous recommendations so they can be reassessed.</p><label class="mt">Attach supporting document<input id="note-file" type="file" accept=".txt,.md,.json,.pdf,.docx,.xlsx,.xlsm,.xltx,.csv"></label><div class="form-actions"><button class="btn primary" type="submit">${icon('plus')} Save evidence</button></div></form></section><section class="panel"><div class="panel-head"><h2>Recorded notes & tests</h2></div><div class="panel-body">${current.timeline.filter(e=>['Note','Test','Attachment','Acceptance','Acknowledgment','Clarification','Investigation','Functional solutioning','Technical solutioning','Approval','Development','Deployment','Verification'].includes(e.kind)).map(e=>`<div class="gap-alert">${badge(e.kind)}<p class="description mt">${esc(e.text)}</p><small class="muted">${e.date_known===false?'Stage date not supplied':time(e.at)}</small></div>`).join('') || '<p class="muted">No notes or tests recorded yet.</p>'}</div></section></div><aside class="panel"><div class="panel-head"><h2>Referenced evidence</h2></div><div class="panel-body">${refs.length?refs.map(r=>`<div class="gap-alert"><button class="source-ref" data-source="${esc(r.source_id)}">${icon('file')}${esc(r.source_id)}</button><h3 class="mt">${esc(r.source_title)}</h3><p>${esc(r.version)} · Updated ${date(r.updated_at)}</p></div>`).join(''):'<p class="muted">Run an evidence search to see relevant sources.</p>'}</div></aside></div>`;
}
function outcomePage() {
  const o=current.outcome;
  if(o) return `<section class="panel"><div class="panel-head"><h2>Recorded outcome</h2>${badge(o.status)}</div><div class="panel-body">${callout(o.imported?'Historical closure imported from the client file. Resolution quality: '+esc(o.resolution_quality)+'. Verification notes are preserved in ITIL workflow. Individual approval and customer confirmation flags were not inferred.':'This outcome was recorded by the consultant. Review it before adding it to reusable knowledge.','success','check')}<div class="mt">${btn('Add outcome to knowledge','promote',false,'book')}</div><div class="outcome-summary">${details([['Selected solution',o.selected_source || o.alternative_solution || 'No selected recommendation'],['Testing',o.tested?'Completed':'Not recorded'],['Customer confirmation',o.customer_confirmed?'Confirmed':'Not recorded']])}${details([['Deployment',o.deployed?'Completed':'Not recorded'],['Recommendation feedback',o.usefulness || 'Not rated'],['Recorded',o.recorded_at?time(o.recorded_at):'Not recorded']])}</div><p class="description">${esc(o.notes)}</p></div></section>`;
  return `<div class="content-grid"><section class="panel"><div class="panel-head"><h2>Record the final outcome</h2><span class="muted">Consultant decision</span></div><form class="panel-body" id="outcome-form"><div class="field-grid"><label>Outcome<select name="status">${['Resolved','Workaround','Unresolved','Escalated','Closed - other'].map(v=>option(v)).join('')}</select></label><label>Recommendation usefulness<select name="usefulness"><option>Not rated</option><option>Useful</option><option>Partly useful</option><option>Not useful</option></select></label><label class="full">Alternative solution, if used<textarea name="alternative_solution" maxlength="12000" placeholder="Describe a different solution if no recommendation was selected."></textarea></label></div><div class="section-label">Validation evidence</div>${[['tested','Testing completed in development / quality'],['customer_confirmed','Customer confirmed the result'],['approved','Deployment / change approved'],['developed','Development completed'],['deployed','Production deployment completed'],['verified','Post-deployment verification completed']].map(([key,label])=>`<label class="check"><input type="checkbox" name="${key}">${label}</label>`).join('')}<label class="mt">Closure notes and evidence<textarea name="notes" required maxlength="12000" placeholder="Summarise the result and reference test records, approvals and remaining limitations."></textarea></label><div class="form-actions"><button class="btn primary" type="submit">${icon('check')} Record outcome</button></div></form></section><aside class="stack"><section class="panel"><div class="panel-head"><h2>Selected solution</h2></div><div class="panel-body">${current.selected_source?`<button class="source-ref" data-source="${esc(current.selected_source)}">${icon('file')}${esc(current.selected_source)}</button><p class="hint">${esc(current.analysis?.results.find(r=>r.source_id===current.selected_source)?.title)}</p>`:'<p class="hint">No recommendation selected. You can select one in Recommendations or document an alternative solution.</p>'}</div></section>${callout(current.type==='Change request'?'A resolved change requires testing, customer confirmation, approval, development, deployment and verification.':'A resolved case requires testing and customer confirmation. Record a workaround separately from a permanent resolution.','warning','shield')}</aside></div>`;
}
function sourceCards() {
  const rows=state.sources.filter(s=>(s.title+' '+s.content+' '+s.id).toLowerCase().includes(knowledge.q.toLowerCase()) && (knowledge.type==='All sources'||s.source_type===knowledge.type));
  return rows.length?`<div class="sources-list">${rows.map(s=>`<article class="source-card"><div class="source-type">${icon('file')}${esc(s.source_type)} <span class="mono">${esc(s.id)}</span></div><h3>${esc(s.title)}</h3><div class="rec-info">${badge(s.validation)}${badge(s.index_status)}<span class="badge">${s.chunk_count || 0} chunks</span></div><p>${esc(s.application)} · ${esc(s.version || 'Release not specified')}<br>Imported ${date(s.created_at)}</p>${s.index_error?`<p class="inline-error">${esc(s.index_error)}</p>`:''}<button class="btn ghost" data-source="${esc(s.id)}">View source ${icon('arrow')}</button></article>`).join('')}</div>`:empty('No knowledge sources found','Upload your documents or paste an approved resolution. The workspace starts empty.',btn('Add knowledge','knowledge-new',true,'plus'));
}
function knowledgePage() {
  return `${heading('Knowledge','Import documents and resolutions to ground AI recommendations.',btn('Add knowledge','knowledge-new',true,'plus'))}${serviceBanner()}${callout('Upload your own exports from SAP, SharePoint, Confluence or your ticket system. Documents are stored in MongoDB; their text is sent to Gemini for embeddings and selected excerpts for analysis.','','book')}<section class="panel mt"><div class="filters"><div class="search">${icon('search')}<input id="knowledge-search" aria-label="Search knowledge" value="${esc(knowledge.q)}" placeholder="Search documents, historical tickets or error codes…"></div><select id="source-filter" aria-label="Filter by source">${['All sources',...new Set(state.sources.map(s=>s.source_type))].map(v=>option(v,knowledge.type)).join('')}</select></div><div id="knowledge-results">${sourceCards()}</div></section>`;
}
function insights() {
  const s=stats(), rows=state.investigations, reviews=rows.flatMap(x=>x.workflow?.evaluations || []), analysed=rows.filter(x=>x.analysis), selected=rows.filter(x=>x.selected_source), rated=rows.filter(x=>x.outcome?.usefulness && x.outcome.usefulness!=='Not rated');
  return `${heading('Insights','Understand investigation outcomes and where knowledge needs to improve.','<span class="demo-pill">WORKSPACE METRICS</span>')}${callout('Counts are calculated from your MongoDB records. Retrieval accuracy and time saved require a separate evaluation dataset.','','chart')}<section class="stats mt">${stat('Investigations',rows.length,'Actual workspace records','folder')}${stat('Evidence searches',analysed.length,'Cases with current search results','search')}${stat('Solutions selected',selected.length,'Awaiting or completed validation','check')}${stat('Feedback recorded',rated.length,'Consultant usefulness ratings','chart')}</section><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Investigation outcomes</h2><span class="muted">${rows.length} total cases</span></div><div class="panel-body">${['New','In progress','Awaiting validation','Resolved','Workaround','Unresolved','Escalated','Closed - other'].map(status=>{const n=rows.filter(x=>x.status===status).length;return `<div class="chart-row"><span>${status}</span><div class="bar-track"><progress max="${Math.max(1,rows.length)}" value="${n}" aria-label="${status}: ${n}"></progress></div><strong>${n}</strong></div>`}).join('')}<p class="metric-note">Outcomes are consultant-recorded. A closed ticket does not automatically mean a permanent fix.</p></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>Knowledge gaps</h2>${badge(String(s.gaps.length))}</div>${s.gaps.length?s.gaps.map(g=>`<div class="gap-alert"><a href="#investigations/${esc(g.id)}/recommendations"><h3>${esc(g.title)}</h3></a><p>${esc(g.application)} · Root cause or supporting evidence needed</p></div>`).join(''):empty('No gaps flagged','Unresolved cases and insufficient evidence will appear here.')}</section><section class="panel"><div class="panel-head"><h2>Evaluation readiness</h2></div><div class="panel-body">${details([['Consultant assessments',String(reviews.length)],['Assessments with unsupported claims',String(reviews.filter(r=>r.claims_supported==='No').length)],['Recall@5 / MRR','Not measured — labelled evaluation set needed'],['Resolution time saved','Not measured — manual comparison needed'],['Recommendation usefulness',rated.length?`${rated.filter(x=>x.outcome.usefulness==='Useful').length} useful / ${rated.length} ratings`:'No feedback yet']])}</div></section></div></div>`;
}
function openModal(title, body) { $('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body"><div id="form-error" class="inline-error hidden" role="alert"></div>${body}</div>`; if(!$('#modal').open) $('#modal').showModal(); }
function formError(message) { const el=$('#form-error'); if(el && $('#modal').open){el.textContent=message;el.classList.remove('hidden');el.scrollIntoView({block:'nearest'});}else toast(message); }
function newInvestigation() {
  draft=null;
  openModal('New investigation',`<p class="muted">Upload or paste a ticket, then review its context. You can also enter details manually.</p><form id="intake-form"><div class="upload">${icon('upload')}<p>Upload your ticket</p><small>TXT, MD, JSON, PDF, DOCX, XLSX or CSV · Up to 5 MB</small><input type="file" id="ticket-file" accept=".txt,.md,.json,.pdf,.docx,.xlsx,.xlsm,.xltx,.csv" aria-label="Upload ticket export"></div><div class="or">OR PASTE TICKET CONTENT</div><label>Ticket details<textarea id="intake-content" name="content" rows="6" placeholder="Paste the issue description, error and investigation history…"></textarea></label><p class="hint">Local parsing uses no AI requests. Review and complete the fields before saving.</p><div class="form-actions"><button type="button" class="btn" data-action="manual">Enter manually</button><button type="submit" class="btn primary">Extract and review ${icon('arrow')}</button></div></form>`);
}
function reviewDraft() {
  openModal('Review ticket context',`${callout('Check the extracted fields. Confirm the customer and SAP context before creating the investigation.','','shield')}<form id="create-form" class="mt"><div class="field-grid"><label class="full">Issue title<input name="title" required maxlength="200" value="${esc(draft.title)}"></label><label>Ticket ID<input name="ticket_id" maxlength="100" value="${esc(draft.ticket_id)}" placeholder="e.g. INC-28492"></label><label>Customer<input name="customer" required maxlength="200" value="${esc(draft.customer || state.customer)}" ${['My Workspace','All'].includes(state.customer)?'':'readonly'} list="customer-names"><datalist id="customer-names">${[...new Set(state.investigations.map(x=>x.customer))].map(v=>option(v)).join('')}</datalist></label><label>Application<input name="application" required maxlength="100" value="${esc(draft.application)}" list="applications" placeholder="e.g. SAP Finance"><datalist id="applications">${['SAP Finance','SAP Procurement','SAP Basis','SAP Integration','SAP HR'].map(v=>option(v)).join('')}</datalist></label><label>System / release<input name="version" required maxlength="100" value="${esc(draft.version)}" placeholder="e.g. S/4HANA 2023"></label><label>Ticket type<select name="type">${['Incident','Service request','Problem','Change request'].map(v=>option(v,draft.type)).join('')}</select></label><label>Priority<select name="priority">${['Low','Medium','High','Critical'].map(v=>option(v,draft.priority)).join('')}</select></label><label>Error code<input name="error_code" maxlength="100" value="${esc(draft.error_code)}"></label><label>Customer customisation<input name="customisation" maxlength="500" value="${esc(draft.customisation)}" placeholder="Optional custom workflow or code"></label>${["platform","module","component","scenario_group"].map(k=>`<label>${esc(k.replaceAll("_"," "))}<input name="${k}" maxlength="100" value="${esc(draft.itil?.[k] || "")}"></label>`).join("")}<label class="full">Clarification<textarea name="clarification" maxlength="12000">${esc(draft.itil?.clarification || "")}</textarea></label><label class="full">Problem description<textarea name="description" rows="4" required maxlength="12000">${esc(draft.description)}</textarea></label></div><div class="section-label">Imported communications · ${draft.timeline.length} entries</div><div class="review-history">${draft.timeline.length?draft.timeline.map(e=>`<p><strong>${time(e.at)} · ${esc(e.author)}</strong><br>${esc(e.text)}</p>`).join(''):'<p>No structured timeline found. Pasted communications remain in the description.</p>'}</div><div class="form-actions"><button type="button" class="btn" data-action="new">Start over</button><button type="submit" class="btn primary">Create investigation ${icon('arrow')}</button></div></form>`);
}
function sourceModal(id) {
  const s=state.sources.find(x=>x.id===id);if(!s)return toast('Source unavailable in this workspace.');
  openModal('Source evidence',`<div class="source-type">${icon('file')}${esc(s.source_type)} · <span class="mono">${esc(s.id)}</span></div><h2 class="mt">${esc(s.title)}</h2><div class="rec-info mt">${badge(s.validation)}${badge(s.index_status)}</div><div class="outcome-summary">${details([['Customer scope',s.customer],['Application / release',s.application+' / '+(s.version || 'Unspecified')]])}${details([['Imported',date(s.created_at)],['Source reference',s.source_reference || s.filename || 'Pasted content'],['Document version',s.document_version || 'Not supplied'],['Section / page',s.source_section || 'Not supplied']])}</div>${s.index_error?callout(esc(s.index_error),'warning','alert'):''}<div class="action-row mt"><button class="btn" data-action="reindex" data-id="${esc(s.id)}">Index / reindex</button><button class="btn" data-action="review-source" data-id="${esc(s.id)}">Record validation</button></div><hr class="divider"><h3>Original source text</h3><p class="source-content">${esc(s.content)}</p>${s.review_notes?`<h3>Review notes</h3><p class="source-content">${esc(s.review_notes)}</p>`:''}`);
}
function knowledgeForm(prefill={}) {
  openModal('Add knowledge',`<form id="source-form"><div class="field-grid"><label class="full">Source title<input name="title" required maxlength="200" value="${esc(prefill.title || '')}"></label><label>Customer scope<input name="customer" required maxlength="200" value="${esc(prefill.customer || state.customer)}" ${["My Workspace","All"].includes(state.customer)?"":"readonly"}></label><label>Application<input name="application" required maxlength="100" value="${esc(prefill.application || '')}"></label><label>System / release<input name="version" maxlength="100" value="${esc(prefill.version || '')}"></label><label>Source type<select name="source_type">${['Document','Historical ticket','Internal KB','SharePoint export','Confluence export','SAP reference'].map(v=>option(v,prefill.source_type)).join('')}</select></label><label>Error code<input name="error_code" maxlength="100" value="${esc(prefill.error_code || '')}"></label><label>Document version<input name="document_version" maxlength="100"></label><label>Section / page<input name="source_section" maxlength="300"></label><label class="full">Original source reference<input name="source_reference" maxlength="1000" value="${esc(prefill.source_reference || '')}" placeholder="Document URL or original ticket ID"></label><label class="full">Upload a document<input type="file" id="knowledge-file" accept=".txt,.md,.json,.pdf,.docx,.xlsx,.xlsm,.xltx,.csv"></label><label class="full">Review extracted text or paste content<textarea id="knowledge-content" name="content" required maxlength="120000" rows="8">${esc(prefill.content || '')}</textarea></label><input type="hidden" name="filename" id="knowledge-filename" value=""></div><p class="hint">Text is saved in MongoDB without an AI request. Index separately when ready. Sources start unverified.</p><div class="form-actions"><button class="btn" type="button" data-action="close">Cancel</button><button class="btn primary" type="submit">Save knowledge</button></div></form>`);
}
function reviewSource(id) {
  const s=state.sources.find(x=>x.id===id);
  openModal('Record source validation',`<form id="source-review-form"><input type="hidden" name="source_id" value="${esc(id)}"><p>${esc(s.title)}</p><label class="mt">Validation status<select name="validation"><option>Reviewed</option><option>Verified</option><option>Outdated</option></select></label>${[['tested','Test evidence recorded'],['customer_confirmed','Customer confirmation recorded'],['deployed','Production deployment recorded']].map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}">${label}</label>`).join('')}<label class="mt">Review notes and evidence references<textarea name="notes" required maxlength="12000"></textarea></label><div class="form-actions"><button type="submit" class="btn primary">Save validation</button></div></form>`);
}
async function readUpload(file) {
  if(file.size>5*1024*1024)throw new Error('Upload a file no larger than 5 MB.');
  const bytes=new Uint8Array(await file.arrayBuffer());let binary='';
  for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));
  return api('/extract',{filename:file.name,file_base64:btoa(binary)});
}
document.addEventListener('click', async event => {
  const el=event.target.closest('button'); if(!el)return; const prior=el.innerHTML;
  try {
    if(el.dataset.source) return sourceModal(el.dataset.source);
    const action=el.dataset.action;
    if(action==='close')return $('#modal').close();
    if(action==='new')return newInvestigation();
    if(action==='manual'){draft={title:'',description:'',ticket_id:'',application:'',version:'',error_code:'',customisation:'',type:'Incident',priority:'Medium',timeline:[]};return reviewDraft();}
    if(action==='knowledge-new')return knowledgeForm();
    if(action==='promote'){const o=current.outcome;return knowledgeForm({customer:current.customer,title:current.title,application:current.application,version:current.version,error_code:current.error_code,source_type:'Historical ticket',source_reference:current.ticket_id || current.id,content:`Issue: ${current.description}\nOutcome: ${o.status}\nResolution: ${o.alternative_solution || o.notes}\nNotes: ${o.notes}\n${current.timeline.filter(e=>['Note','Test','Attachment','Acceptance','Acknowledgment','Clarification','Investigation','Functional solutioning','Technical solutioning','Approval','Development','Deployment','Verification'].includes(e.kind)).map(e=>`${e.at} ${e.kind}: ${e.text}`).join('\n')}`});}
    if(action==='review-source')return reviewSource(el.dataset.id);
    if(action==='reindex'){el.disabled=true;el.textContent='Indexing…';const source=await api(`/sources/${el.dataset.id}/reindex`,{});await refresh();sourceModal(source.id);toast(source.index_status==='Ready'?'Source indexed.':source.index_error);}
    if(action==='check-ai'){el.disabled=true;el.textContent='Checking…';try{await api('/ai/check',{});aiConnection='Connected';await refresh();toast('Gemini generation verified with one request.');}catch(error){aiConnection='Check failed';await refresh();throw error;}}

    if(action==='analyze') {el.disabled=true;el.textContent='Searching permitted evidence…';await api(`/investigations/${current.id}/analyze`,{});await refresh();go(`investigations/${current.id}/recommendations`);toast('Evidence search complete. Review applicability before selecting a solution.');}
    if(el.dataset.decision){el.disabled=true;await api(`/investigations/${current.id}/decision`,{source_id:el.dataset.id,decision:el.dataset.decision});await refresh();toast(el.dataset.decision==='Accepted'?'Selected for validation. Record test evidence before the outcome.':'Recommendation rejected.');}
    if(action==='retry'){try{await refresh();}catch(e){showConnectionError(e);}}
  }catch(error){formError(error.message);}finally{el.disabled=false;if(el.isConnected)el.innerHTML=prior;}
});
document.addEventListener('input',event=>{
  if(event.target.id==='ticket-search'){filters.q=event.target.value;$('#tickets-table').innerHTML=ticketTable(filteredTickets());}
  if(event.target.id==='knowledge-search'){knowledge.q=event.target.value;$('#knowledge-results').innerHTML=sourceCards();}
});
document.addEventListener('change',async event=>{
  const {id,value}=event.target;
  if(id==='knowledge-file' && event.target.files[0]){const submit=$('#source-form button[type=submit]');submit.disabled=true;try{const result=await readUpload(event.target.files[0]);$('#knowledge-content').value=result.content;$('#knowledge-filename').value=result.filename;toast('Document extracted. Review the text before saving.');}catch(e){formError(e.message);}finally{submit.disabled=false;}return;}
  if(id==='status-filter'||id==='type-filter'){filters[id==='status-filter'?'status':'type']=value;$('#tickets-table').innerHTML=ticketTable(filteredTickets());}
  if(id==='source-filter'){knowledge.type=value;$('#knowledge-results').innerHTML=sourceCards();}
});
document.addEventListener('submit',async event=>{
  event.preventDefault(); const form=event.target, submit=$('button[type="submit"]',form), original=submit?.innerHTML;
  if(submit){submit.disabled=true;submit.textContent='Saving…';}
  try {
    if(form.id==='local-search-form'){
      const result=await api(`/investigations/${current.id}/search`,Object.fromEntries(new FormData(form)));
      $('#local-search-results').innerHTML=result.results.map(r=>`<div class="gap-alert"><button class="source-ref" data-source="${esc(r.source_id)}">${esc(r.title)}</button><p class="description">${esc(r.excerpt)}</p><small>${esc(r.validation)} � Keyword matches: ${r.score}</small></div>`).join('') || '<p>No matching permitted sources.</p>';
    }
    if(form.id==='workspace-form'){
      const data=Object.fromEntries(new FormData(form));data.revision=current.revision;data.id=data.record_id;
      if(data.kind==='proposal'){data.citations=[0,1,2,3,4].map(i=>({source_id:data['source_'+i],section:data['section_'+i],quote:data['quote_'+i]})).filter(c=>c.source_id || c.quote);}
      await api(`/investigations/${current.id}/workspace`,data);$('#modal').close();await refresh();toast('Workspace evidence saved.');
    }
    if(form.id==='source-form'){
      const source=await api('/sources',{...Object.fromEntries(new FormData(form)),index_now:false});$('#modal').close();await refresh();go('knowledge');toast(source.index_status==='Ready'?'Knowledge saved and indexed.':'Document saved. Index explicitly when ready.');
    }
    if(form.id==='source-review-form'){
      const data=Object.fromEntries(new FormData(form));for(const key of ['tested','customer_confirmed','deployed'])data[key]=Boolean(data[key]);await api(`/sources/${data.source_id}/review`,data);await refresh();sourceModal(data.source_id);toast('Validation recorded.');
    }
    if(form.id==='intake-form'){
      const file=$('#ticket-file').files[0];let content=$('#intake-content').value,filename='';
      if(file){const extracted=await readUpload(file);content=extracted.content;filename=extracted.filename;}
      draft=await api('/intake',{content,filename});reviewDraft();
    }
    if(form.id==='create-form'){
      const data={...Object.fromEntries(new FormData(form)),timeline:draft.timeline,customer:form.elements.customer?.value || state.customer,itil:{...(draft.itil || {}),...Object.fromEntries(['platform','module','component','scenario_group','clarification'].map(k=>[k,form.elements[k]?.value || draft.itil?.[k] || '']))}};
      const item=await api('/investigations',data);$('#modal').close();await refresh();go(`investigations/${item.id}/overview`);toast('Investigation created. Review the context and find supporting evidence.');
    }
    if(form.id==='note-form'){
      const note=Object.fromEntries(new FormData(form)),file=$('#note-file').files[0];if(file){const extracted=await readUpload(file);note.text+=(note.text?'\n':'')+extracted.filename+'\n'+extracted.content;note.kind='Attachment';}await api(`/investigations/${current.id}/note`,note);await refresh();toast('Evidence saved. Run a fresh search to include your findings.');
    }
    if(form.id==='outcome-form'){
      const data=Object.fromEntries(new FormData(form));for(const key of ['tested','customer_confirmed','approved','developed','deployed','verified'])data[key]=Boolean(data[key]);
      await api(`/investigations/${current.id}/outcome`,data);await refresh();toast('Outcome recorded. Your investigation trail is saved in MongoDB.');
    }
  }catch(error){formError(error.message);}finally{if(submit){submit.disabled=false;submit.innerHTML=original;}}
});
window.addEventListener('hashchange',render);
refresh().catch(showConnectionError);
function workspacePage() {
  const w=current.workflow || {}, d=current.itil || {};
  const stageNames=['Acceptance','Acknowledgment','Clarification','Solutioning',...(current.type==='Change request'?['Approval','Development','Deployment','Verification']:[])];
  const section=(title,body)=>`<section class="panel"><div class="panel-head"><h2>${title}</h2></div><div class="panel-body">${body}</div></section>`;
  const edit=(kind,id='',label='Add')=>`<button class="btn small" data-work-kind="${kind}" data-work-id="${esc(id)}">${esc(label)}</button>`;
  const field=(label,value)=>`<p class="description"><strong>${esc(label)}:</strong> ${esc(value || 'Not recorded')}</p>`;
  const requirements=w.requirements || [], scenarios=w.scenarios || [];
  return `<div class="stack">${callout('Consultant-authored workspace. Saving and reviewing evidence uses no AI requests. Historical notes do not imply completed stages.')}
    ${section('Lifecycle summary',field('Original request',current.description)+field('Clarified requirement',d.clarification)+field('Functional solution',[(d.functional_solutioning || ''),...(w.proposals || []).filter(r=>r.category==='Functional').map(r=>r.title+': '+r.detail)].filter(Boolean).join('\n\n'))+field('Technical solution',[(d.technical_solutioning || ''),...(w.proposals || []).filter(r=>r.category==='Technical').map(r=>r.title+': '+r.detail)].filter(Boolean).join('\n\n'))+field('Verification',d.verification)+field('Closure',current.outcome?.notes)+`<p class="mt">${requirements.filter(r=>r.status==='Needs confirmation').length} requirements need confirmation · ${scenarios.filter(r=>r.status==='Passed').length}/${scenarios.length} scenarios passed.</p><a href="#investigations/${current.id}/timeline">View supporting timeline and decisions</a>`)}
    ${section('Search evidence without AI',`<form id="local-search-form"><label>Keywords<input name="query" required maxlength="500" placeholder="Batch vendor expiry�"></label><button class="btn mt" type="submit">Search local knowledge</button></form><div id="local-search-results" class="mt"></div>`)}
    ${section('SAP applicability',details(['plant','transaction','program_include','enhancement','configuration_path','affected_process'].map(k=>[k.replaceAll('_',' '),d[k] || 'Not recorded']))+edit('context','','Edit applicability'))}
    ${section('Lifecycle ownership',stageNames.map(name=>{const r=w.stages?.[name] || {};return `<div class="gap-alert"><h3>${esc(name)}</h3>${badge(r.status || 'Not started')}${field('Owner',r.owner)}${field('Evidence',r.evidence)}${r.updated_at?`<small>${time(r.updated_at)} · ${esc(r.author)}</small>`:''}<div class="mt">${edit('stage',name,'Update stage')}</div></div>`;}).join(''))}
    ${section('Requirements and open questions',requirements.map(r=>`<div class="gap-alert"><h3>${esc(r.title)}</h3>${badge(r.status)}${field('Detail',r.detail)}${field('Confirmation evidence',r.evidence)}${edit('requirement',r.id,'Edit')}</div>`).join('')+edit('requirement','','Add requirement'))}
    ${section('Functional and technical proposals',(w.proposals || []).map(r=>`<div class="gap-alert"><h3>${esc(r.category)} · ${esc(r.title)}</h3>${field('Proposal',r.detail)}${field('Limitations / unconfirmed assumptions',r.limitations)}${r.citations.length?r.citations.map(c=>`<blockquote>${esc(c.quote)}<small><button class="source-ref" data-source="${esc(c.source_id)}">${esc(c.source_id)}</button> · ${esc(c.section)}</small></blockquote>`).join(''):callout('No source citations supplied. This is an unsupported consultant draft.','warning')}${edit('proposal',r.id,'Edit')}</div>`).join('')+edit('proposal','','Add proposal'))}
    ${section('Consultant evaluation',(w.evaluations || []).map(r=>`<div class="gap-alert"><h3>${esc(r.title)}</h3>${field('Reviewer',r.reviewer)}${field('Summary complete',r.summary_complete)}${field('Claims supported',r.claims_supported)}${field('Scenarios covered',r.scenarios_covered)}${field('Review evidence',r.evidence)}<small>Assessed ticket revision ${esc(r.ticket_revision)} � ${time(r.updated_at)}</small></div>`).join('')+edit('evaluation','','Record assessment'))}
    ${section('Verification scenarios',scenarios.map(r=>`<div class="gap-alert"><h3>${esc(r.title)}</h3>${badge(r.status)}${field('Expected',r.expected)}${field('Actual',r.actual)}${field('Environment / tester',[r.environment,r.tester].filter(Boolean).join(' / '))}${field('Evidence',r.evidence)}${edit('scenario',r.id,'Edit')}</div>`).join('')+edit('scenario','','Add scenario'))}</div>`;
}

function workspaceForm(kind,id) {
  const w=current.workflow || {};
  const row=kind==='context'?current.itil || {}:kind==='stage'?w.stages?.[id] || {}:(w[kind+'s'] || []).find(r=>r.id===id) || {};
  const input=(key,label,required=false)=>`<label class="mt">${esc(label)}<input name="${key}" maxlength="500" value="${esc(row[key] || '')}" ${required?'required':''}></label>`;
  const area=(key,label,required=false)=>`<label class="mt">${esc(label)}<textarea name="${key}" maxlength="12000" ${required?'required':''}>${esc(row[key] || '')}</textarea></label>`;
  const select=(key,label,values)=>`<label class="mt">${esc(label)}<select name="${key}">${values.map(v=>option(v,row[key])).join('')}</select></label>`;
  let body='';
  if(kind==='context') body=['plant','transaction','program_include','enhancement','configuration_path','affected_process'].map(k=>input(k,k.replaceAll('_',' '))).join('');
  if(kind==='stage') body=`<input type="hidden" name="name" value="${esc(id)}">`+select('status','Stage status',['Not started','In progress','Blocked','Completed'])+input('owner','Owner',true)+area('evidence','Evidence (required for completion)');
  if(kind==='requirement') body=input('title','Requirement or question',true)+area('detail','Rule / ambiguity')+select('status','Confirmation',['Needs confirmation','Confirmed','Rejected'])+area('evidence','Decision and supporting evidence');
  if(kind==='scenario') body=input('title','Scenario',true)+area('expected','Expected result',true)+select('status','Test result',['Not run','Passed','Failed','Blocked'])+area('actual','Actual result')+input('environment','Test environment')+input('tester','Tester')+area('evidence','Test record reference / evidence');
  if(kind==='evaluation') body=input('title','Review title',true)+input('reviewer','Reviewer',true)+['summary_complete','claims_supported','scenarios_covered'].map(k=>select(k,k.replaceAll('_',' '),['Not assessed','Yes','No'])).join('')+area('evidence','Findings / expected behaviour',true);
  if(kind==='proposal') body=select('category','Proposal type',['Functional','Technical'])+input('title','Title',true)+area('detail','Proposed solution',true)+area('limitations','Limitations / unconfirmed assumptions')+`<div class="section-label">Supporting evidence (up to five sources)</div>${[0,1,2,3,4].map(i=>{const c=row.citations?.[i] || {};return `<fieldset class="mt"><legend>Source ${i+1}</legend><label>Knowledge source<select name="source_${i}"><option value="">Select a source</option>${state.sources.filter(s=>[current.customer,'General'].includes(s.customer)).map(s=>`<option value="${esc(s.id)}" ${s.id===c.source_id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>Section / page<input name="section_${i}" value="${esc(c.section || '')}" maxlength="300"></label><label>Exact supporting quotation<textarea name="quote_${i}" maxlength="3000">${esc(c.quote || '')}</textarea></label></fieldset>`;}).join('')}<p class="hint">Copy quotations from Knowledge. Each quotation is checked against the original source. Without citations this remains an unsupported draft.</p>`;
  openModal('Edit '+(kind==='stage'?id:kind),`<form id="workspace-form"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="record_id" value="${kind==='stage'?'':esc(id)}">${body}<div class="form-actions"><button type="submit" class="btn primary">Save evidence</button></div></form>`);
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-work-kind]');if(button)workspaceForm(button.dataset.workKind,button.dataset.workId);});

function showConnectionError(error) {
  $('#app').innerHTML=`<main class="setup-screen"><div class="brand-icon">${icon('layers')}</div><h1>Connect your workspace</h1><p class="inline-error">${esc(error.message)}</p><section class="panel"><div class="panel-body"><h2>Configure .env</h2><p class="mt">Set <code>MONGODB_URI</code> to your MongoDB connection string and add your <code>GEMINI_API_KEY</code>. Restart the server after editing.</p><p class="mt">For local MongoDB, start Docker Desktop and run <code>docker compose up -d mongodb</code>. MongoDB Atlas works with its connection URI too.</p><p class="hint">No sample records or fallback database are loaded. Your workspace starts empty.</p></div></section><div class="mt">${btn('Retry connection','retry',true)}</div></main>`;
}
